<?php
declare(strict_types=1);

/**
 * Phase 7c (E-commerce) end-to-end test: E-commerce templates 02–10 generated by tools/template-factory.
 *
 *   php tests/phase7c_ecommerce_test.php <builder-url> <email> <password> <website-ids> <db-dsn> [export-website-id]
 *
 * <website-ids> is a comma-separated list of nine freshly generated websites, one per template, in order
 * ecommerce_template_02 … ecommerce_template_10. <db-dsn> is "dsn|user|password" for the builder database.
 */

require __DIR__ . '/support.php';

[$_, $base, $email, $password, $ids, $dsn, $exportId] = $argv + [null, 'http://127.0.0.1:8080', 'info@channelsoftech.com', '', '', '', '0'];
$base = rtrim((string) $base, '/');
$ids = array_map('intval', array_filter(explode(',', (string) $ids)));
$sfx = substr(bin2hex(random_bytes(3)), 0, 6);
$pass = $fail = 0;
$started = microtime(true);
$root = dirname(__DIR__);

// Expected design per template: prefix, hero/header/footer variants and a phrase from the demo copy.
$expect = [
    '02' => ['kth', 'split', 'center', 'columns', 'overlay', 'tiles', 'Heritage prints, made for today.'],
    '03' => ['vlt', 'stack', 'pill', 'centered', 'plain', 'circles', 'Gear that keeps up with you.'],
    '04' => ['gbo', 'panel', 'dark', 'band', 'plain', 'circles', 'Real food, straight from the farm.'],
    '05' => ['dwp', 'split', 'pill', 'centered', 'overlay', 'circles', 'Skincare that feels like a ritual.'],
    '06' => ['aur', 'editorial', 'center', 'centered', 'overlay', 'tiles', 'Jewellery to be treasured for generations.'],
    '07' => ['ttt', 'stack', 'pill', 'band', 'plain', 'circles', 'Toys that grow with curious minds.'],
    '08' => ['erc', 'cover', 'dark', 'columns', 'overlay', 'tiles', 'Fresh coffee, from estate to cup.'],
    '09' => ['stz', 'panel', 'dark', 'columns', 'plain', 'tiles', 'Train harder. Recover smarter.'],
    '10' => ['ppl', 'editorial', 'center', 'band', 'plain', 'circles', 'Stories, notebooks and the joy of paper.'],
];
$known = ['mrd', 'kst', 'hzt', 'sfr', 'lvh', 'skl', 'ldg', 'crl', 'lyc', 'trm', 'nbf', 'vtx', 'gfh', 'icw', 'bpt', 'scr', 'cmc', 'hbc', 'pls', 'lac', 'apx', 'mit', 'cis', 'cfa', 'rsp', 'wsm', 'lgb', 'pcr', 'srh', 'scd', 'cse', 'lhc', 'psd', 'rvp', 'vga', 'mnw', 'chi'];

[$d, $du, $dp] = explode('|', (string) $dsn) + ['', '', ''];
$pdo = new PDO($d, $du, $dp, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);

echo "\n== Template files ==\n";
$prefixes = [];
$descriptions = [];
$designs = [];
foreach ($expect as $n => [$p, $hero, $header, $footer, $card, $cats]) {
    $dir = "$root/templates/ecommerce/ecommerce_template_$n";
    $m = json_decode((string) @file_get_contents("$dir/manifest.json"), true) ?: [];
    $css = (string) @file_get_contents("$dir/assets/css/style.css");
    $layout = (string) @file_get_contents("$dir/layouts/default.php");
    $prefixes[] = $p;
    $descriptions[] = $m['description'] ?? '';
    $designs[] = "$hero/$header/$footer/$card/$cats/" . ($m['theme']['defaults']['heading_font'] ?? '') . '/' . ($m['theme']['defaults']['primary'] ?? '');

    $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
    $leftover = [];
    $foreign = [];
    foreach ($files as $f) {
        if (!preg_match('/\.(php|css|js|json)$/', $f->getFilename())) {
            continue;
        }
        $txt = (string) file_get_contents($f->getPathname());
        if (str_contains($txt, '{{')) {
            $leftover[] = $f->getFilename();
        }
        foreach ($known as $k) {
            if (preg_match('/(?<![a-z-])' . $k . '-[a-z]/', $txt)) {
                $foreign[] = $f->getFilename() . ":$k";
            }
        }
    }
    check("$n manifest: id, name, category, version, unique description", ($m['id'] ?? '') === "ecommerce_template_$n" && ($m['category'] ?? '') === 'ecommerce' && preg_match('/^\d+\.\d+\.\d+$/', (string) ($m['version'] ?? '')) === 1 && strlen((string) ($m['description'] ?? '')) > 80);
    check("$n uses its own prefix \"$p\" throughout; no placeholders or other templates' classes left", str_contains($layout, "<body class=\"$p ") && !$leftover && !$foreign && preg_match_all("/\\.$p-[a-z]/", $css) > 200, json_encode([$leftover, $foreign]));
    check("$n stylesheet is theme-driven (no hard-coded brand colours)", !str_contains(strtoupper($css), strtoupper((string) ($m['theme']['defaults']['primary'] ?? '#'))) && !str_contains(strtoupper($css), strtoupper((string) ($m['theme']['defaults']['secondary'] ?? '#'))) && str_contains($css, 'var(--wb-primary)'));
    $demo = json_decode((string) @file_get_contents("$dir/demo.json"), true) ?: [];
    preg_match_all('#theme:images/([a-z0-9._-]+)#', json_encode($demo, JSON_UNESCAPED_SLASHES), $im);
    $missing = array_filter(array_unique($im[1]), static fn ($f) => !is_file("$dir/assets/images/$f"));
    $slugs = array_column($demo['shop']['products'] ?? [], 'slug');
    $noImg = array_filter($slugs, static fn ($s) => !is_file("$dir/assets/images/product-$s.svg") || !is_file("$dir/assets/images/product-$s-2.svg"));
    check("$n demo images all exist (" . count(array_unique($im[1])) . " referenced), two images per product, preview.jpg present", !$missing && count($slugs) === 12 && !$noImg && is_file("$dir/assets/images/hero.svg") && is_file("$dir/assets/images/promo.svg") && is_file("$dir/preview.jpg"), json_encode([array_values($missing), array_values($noImg)]));
    $shop = $demo['shop'] ?? [];
    check("$n demo shop: enabled, 4 categories, 12 products with GST/HSN and paise prices, variants, coupons; no secrets", ($shop['settings']['enabled'] ?? false) === true && count($shop['categories'] ?? []) === 4
        && !array_filter($shop['products'] ?? [], static fn ($p) => !is_int($p['price'] ?? null) || $p['price'] < 1000 || ($p['hsn'] ?? '') === '' || !isset($p['gst_rate']))
        && array_filter($shop['products'] ?? [], static fn ($p) => !empty($p['variants'])) && count($shop['coupons'] ?? []) >= 1
        && !preg_match('/key_secret|webhook_secret|api_key|password/i', json_encode($demo)) && ($m['features'] ?? []) === ['contact', 'ecommerce'] && ($m['theme']['defaults']['header_style'] ?? '') === 'announce');
    check("$n has its \"$card\" product card and \"$cats\" category partials", is_file("$dir/partials/product-card.php") && str_contains((string) file_get_contents("$dir/partials/product-card.php"), "$p-product-$card") && is_file("$dir/sections/product_categories.php") && str_contains((string) file_get_contents("$dir/sections/product_categories.php"), "$p-cats-$cats"));
    $pt = $m['page_types'] ?? [];
    $homeTypes = array_column($demo['pages']['']['sections'] ?? [], 'type');
    check("$n home page type matches its demo; all section types have a view", ($pt['home']['default_sections'] ?? null) === $homeTypes && !array_filter($m['section_types'] ?? [], static fn ($t) => !is_file("$dir/sections/$t.php")));
}
check('Nine distinct prefixes, none shared with existing templates', count(array_unique($prefixes)) === 9 && !array_intersect($prefixes, $known));
check('Nine distinct descriptions and design combinations', count(array_unique($descriptions)) === 9 && count(array_unique($designs)) === 9);

$b = new Client($base);
check('Builder login', ($b->login($email, $password)['json']['ok'] ?? false) === true);
$rows = $pdo->query("SELECT t.code, t.status, c.slug FROM wb_templates t JOIN wb_categories c ON c.id = t.category_id WHERE t.code LIKE 'ecommerce_template_%'")->fetchAll();
$byCode = array_column($rows, null, 'code');
$okReg = true;
foreach (array_keys($expect) as $n) {
    $okReg = $okReg && ($byCode["ecommerce_template_$n"]['status'] ?? '') === 'active' && ($byCode["ecommerce_template_$n"]['slug'] ?? '') === 'ecommerce';
}
check('All nine registered and active in the E-commerce category', $okReg, json_encode($byCode));
spl_autoload_register(static function (string $class) use ($root): void {
    if (str_starts_with($class, 'App\\') && is_file($f = $root . '/app/' . str_replace('\\', '/', substr($class, 4)) . '.php')) {
        require $f;
    }
});
$cats = $pdo->query('SELECT slug FROM wb_categories')->fetchAll(PDO::FETCH_COLUMN);
$report = [];
foreach (array_keys($expect) as $n) {
    $v = (new App\Modules\Templates\ManifestValidator())->validate("$root/templates/ecommerce/ecommerce_template_$n", $cats, "ecommerce_template_$n", 'ecommerce');
    if ($v->errors() || $v->warnings()) {
        $report[$n] = [$v->errors(), $v->warnings()];
    }
}
check('Template validator: no errors or warnings for any of the nine', !$report, json_encode($report));

preg_match('/font-monospace" value="([A-Za-z0-9]+)"/', $b->req('GET', 'settings', [], false)['body'], $mm);
$qa = 'qa:' . ($mm[1] ?? '');

echo "\n== Generated sites ==\n";
$n = 2;
foreach ($ids as $wid) {
    $key = sprintf('%02d', $n++);
    [$p, $hero, $header, $footer, $card, $cats, $phrase] = $expect[$key];
    $demo = json_decode((string) file_get_contents("$root/templates/ecommerce/ecommerce_template_$key/demo.json"), true);
    $tp = (string) $pdo->query('SELECT table_prefix FROM wb_websites WHERE id = ' . $wid)->fetchColumn();
    $pdo->exec("DELETE FROM {$tp}login_attempts WHERE ip IN ('127.0.0.1', '::1')");
    $pdo->exec("UPDATE {$tp}contact_submissions SET created_at = created_at - INTERVAL 2 HOUR WHERE ip IN ('127.0.0.1', '::1')");
    $owner = "ecm{$key}owner$sfx@example.com";
    $r = $b->req('POST', "websites/$wid/admin-account", ['email' => $owner, 'name' => 'Owner']);
    $siteUrl = substr(rtrim((string) ($r['json']['url'] ?? ''), '/'), 0, -strlen('admin'));
    $host = (string) preg_replace('#^(https?://[^/]+).*$#', '$1', $siteUrl);
    $pub = new Client($siteUrl);
    $pub->basic = $qa;

    $counts = [(int) $pdo->query("SELECT COUNT(*) FROM {$tp}products")->fetchColumn(), (int) $pdo->query("SELECT COUNT(*) FROM {$tp}product_categories")->fetchColumn(), (int) $pdo->query("SELECT COUNT(*) FROM {$tp}coupons")->fetchColumn()];
    check("$key demo shop imported: 12 products, 4 categories, coupons", $counts[0] === 12 && $counts[1] === 4 && $counts[2] === count($demo['shop']['coupons']), json_encode($counts));

    $home = $pub->req('GET', '', [], false);
    $h = $home['body'];
    check("$key home 200 with body class \"$p\", $header header, $hero hero, $footer footer", $home['code'] === 200 && str_contains($h, "<body class=\"$p $p-mood-") && str_contains($h, "$p-header-$header") && str_contains($h, "$p-hero-$hero") && str_contains($h, "$p-footer-$footer"));
    check("$key hero copy, menu with Shop dropdown of categories, legal links", str_contains($h, htmlspecialchars($phrase, ENT_QUOTES)) && str_contains($h, "$p-shop-nav") && substr_count($h, 'shop?c=') >= 4 && substr_count($h, 'class="nav-link') >= 5 && str_contains($h, 'shipping-returns') && str_contains($h, 'privacy-policy'));
    $free = 'Free delivery on orders above ₹' . number_format(intdiv((int) $demo['shop']['settings']['free_shipping_above'], 100));
    $cod = (bool) $demo['shop']['settings']['cod_enabled'];
    check("$key announcement bar (free delivery" . ($cod ? ', COD' : ', no COD') . "), search and cart icons, trust strip in the footer", str_contains($h, "class=\"$p-announce\"") && str_contains($h, $free) && str_contains($h, 'Cash on delivery available') === $cod && str_contains($h, "$p-shop-icons") && str_contains($h, 'aria-label="Cart, 0 items"') && str_contains($h, "class=\"$p-trust"));
    check("$key home sections: $cats categories (4), featured and new products (4 + 4, $card cards), features, testimonials, CTA", str_contains($h, "$p-cats-$cats") && substr_count($h, "class=\"$p-cat\"") === 4 && substr_count($h, "class=\"$p-product $p-product-$card") === 8 && substr_count($h, "$p-products-head") === 2 && substr_count($h, "$p-quote") >= 3 && str_contains($h, "$p-cta"));
    check("$key product cards show price, struck MRP and badges; simple products add to cart, others link to options", str_contains($h, "$p-price") && str_contains($h, '<s>') && str_contains($h, "$p-flag") && str_contains($h, 'name="product_id"') && str_contains($h, 'name="action" value="add"'));
    preg_match_all('#src="([^"]+/theme/assets/images/[^"?]+)#', $h, $srcs);
    $bad = 0;
    foreach (array_slice(array_unique($srcs[1]), 0, 6) as $src) {
        $bad += $pub->req('GET', $host . html_entity_decode($src), [], false)['code'] === 200 ? 0 : 1;
    }
    check("$key theme images served", count($srcs[1]) >= 8 && $bad === 0);

    $pagesOk = true;
    foreach (['about' => "$p-about", 'help' => "$p-faq", 'contact' => "$p-form", 'shipping-returns' => "$p-rich", 'privacy-policy' => "$p-rich", 'terms-and-conditions' => "$p-rich"] as $slug => $marker) {
        $pg = $pub->req('GET', $slug, [], false);
        $pagesOk = $pagesOk && $pg['code'] === 200 && str_contains($pg['body'], $marker) && str_contains($pg['body'], "$p-banner") && str_contains($pg['body'], "$p-crumbs");
    }
    check("$key inner pages: our story, help & FAQ, contact, shipping & returns, legal — with banner and breadcrumbs", $pagesOk);
    $sr = $pub->req('GET', 'shipping-returns', [], false)['body'];
    check("$key shipping & returns page states the store's own delivery and return terms", str_contains($sr, $free === '' ? 'x' : number_format(intdiv((int) $demo['shop']['settings']['free_shipping_above'], 100))) && str_contains($sr, $cod ? 'Cash on delivery' : 'not available'));
    $nf = $pub->req('GET', 'no-such-page-' . $sfx, [], false);
    check("$key 404 page uses the template", $nf['code'] === 404 && str_contains($nf['body'], "$p-404"));

    $cat = $pub->req('GET', 'shop', [], false);
    $c = $cat['body'];
    check("$key catalogue: 12 products in the template's $card cards, category chips styled by the template", $cat['code'] === 200 && substr_count($c, "class=\"$p-product $p-product-$card") === 12 && substr_count($c, 'wbshop-chip') >= 5 && str_contains($c, "<body class=\"$p "));
    $first = $demo['shop']['categories'][0]['slug'];
    $cc = $pub->req('GET', "shop?c=$first", [], false);
    $inCat = count(array_filter($demo['shop']['products'], static fn ($x) => $x['category'] === $first));
    check("$key category page lists its $inCat products", $cc['code'] === 200 && substr_count($cc['body'], "class=\"$p-product $p-product-$card") === $inCat);
    $simple = array_values(array_filter($demo['shop']['products'], static fn ($x) => empty($x['variants']) && ($x['stock'] ?? 0) > 0))[0];
    $pp = $pub->req('GET', 'shop/product/' . $simple['slug'], [], false);
    check("$key product page: gallery of two images, price, add to cart and buy now, related products in template cards", $pp['code'] === 200 && str_contains($pp['body'], 'product-' . $simple['slug'] . '-2.svg') && str_contains($pp['body'], 'value="checkout"') && str_contains($pp['body'], "$p-product-$card"));
    preg_match('/name="_t" value="([^"]+)"/', $pp['body'], $t);
    preg_match('/name="product_id" value="(\d+)"/', $pp['body'], $pid);
    $r = $pub->req('POST', 'shop/cart', ['_t' => $t[1] ?? '', 'action' => 'add', 'product_id' => $pid[1] ?? '', 'qty' => 2], false);
    $cart = $pub->req('GET', 'shop/cart', [], false)['body'];
    $price = '₹' . number_format(intdiv((int) $simple['price'], 100) * 2);
    check("$key add to cart: cart shows the line and subtotal $price; header count updates", $r['code'] === 303 && substr_count($cart, 'class="wbshop-line"') === 1 && str_contains($cart, "<dt>Items (2)</dt><dd>$price</dd>") && str_contains($pub->req('GET', '', [], false)['body'], 'aria-label="Cart, 2 items"'), $price);
    $co = $pub->req('GET', 'shop/checkout', [], false);
    check("$key checkout page renders in the template", $co['code'] === 200 && str_contains($co['body'], "<body class=\"$p ") && str_contains($co['body'], 'wbshop-fields'));

    $html = $pub->req('GET', 'contact', [], false)['body'];
    preg_match('/<form class="' . $p . '-form" method="post" action="([^"]*\/form\/contact)"/', $html, $act);
    preg_match('/name="_t" value="([^"]+)"/', $html, $t);
    preg_match('/name="_back" value="([^"]*)"/', $html, $bk);
    sleep(3);
    $post = $pub->req('POST', $host . html_entity_decode($act[1] ?? ''), ['_t' => $t[1] ?? '', '_back' => $bk[1] ?? '', 'name' => "Client $key $sfx", 'email' => "c$key$sfx@example.com", 'phone' => '+91 98450 22222', 'subject' => 'Order question', 'message' => "Question about template $key."], false);
    $after = $pub->req('GET', (string) $post['location'], [], false)['body'];
    $saved = (int) $pdo->query("SELECT COUNT(*) FROM {$tp}contact_submissions WHERE name = " . $pdo->quote("Client $key $sfx"))->fetchColumn();
    check("$key contact form submits, shows the success message and stores the enquiry", isset($act[1]) && str_contains($after, "$p-form-alert is-sent") && $saved === 1);
}
check('Nine websites tested', count($ids) === 9);

if ((int) $exportId > 0) {
    echo "\n== Export ==\n";
    $r = $b->req('POST', "websites/$exportId/exports", ['type' => 'full', 'prefix' => 'site_']);
    $eid = $r['json']['state']['export_id'] ?? 0;
    $st = ['status' => 'running'];
    for ($i = 0; $i < 20 && ($st['status'] ?? '') === 'running'; $i++) {
        $st = $b->req('POST', "websites/$exportId/exports/$eid/step")['json']['state'] ?? ['status' => 'error'];
    }
    check('Full export of a factory-built site completes', ($st['status'] ?? '') === 'done', json_encode($st));
    $zip = $b->req('GET', "websites/$exportId/exports/$eid/download", [], false);
    $tmp = tempnam(sys_get_temp_dir(), 'z7e');
    file_put_contents($tmp, $zip['body']);
    $za = new ZipArchive();
    $names = [];
    if ($za->open($tmp) === true) {
        for ($i = 0; $i < $za->numFiles; $i++) {
            $names[] = $za->getNameIndex($i);
        }
        $za->close();
    }
    unlink($tmp);
    $flat = implode("\n", $names);
    check('Export contains the template (layout, stylesheet, product images, shop partials)', str_contains($flat, 'layouts/default.php') && str_contains($flat, 'assets/css/style.css') && str_contains($flat, 'assets/images/hero.svg') && preg_match('#assets/images/product-[a-z0-9-]+-2\\.svg#', $flat) === 1 && str_contains($flat, 'partials/product-card.php') && str_contains($flat, 'partials/announce.php'));
    check('Export contains no factory tooling', !str_contains($flat, 'template-factory') && !preg_match('/\.py$/m', $flat));
}

printf("\n%d passed, %d failed (%.1fs)\n", $pass, $fail, microtime(true) - $started);
exit($fail ? 1 : 0);
